parameters.functionCode:
// Validate required fields
const required = ['project_name', 'country', 'technology_type', 'ownership_model', 'estimated_cost_usd'];
const missing = required.filter(field => !$json[field]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Normalize ownership model
const ownershipMap = {
  'cooperative': 'community_cooperative',
  'coop': 'community_cooperative',
  'community': 'community_cooperative',
  'public': 'public_utility',
  'government': 'public_utility',
  'hybrid': 'public_community_hybrid',
  'private': 'private_ipp'
};

const normalizedOwnership = ownershipMap[($json.ownership_model || '').toLowerCase()] || $json.ownership_model;

// Normalize technology type
const techMap = {
  'mini-grid': 'solar_mini_grid',
  'minigrid': 'solar_mini_grid',
  'solar minigrid': 'solar_mini_grid',
  'standalone': 'solar_standalone',
  'shs': 'solar_home_systems'
};

const normalizedTech = techMap[($json.technology_type || '').toLowerCase()] || $json.technology_type;

return [{
  json: {
    project_intake: {
      project_name: $json.project_name,
      country: $json.country,
      location_description: $json.location_description || '',
      technology_type: normalizedTech,
      capacity_kw: $json.capacity_kw || null,
      target_beneficiaries: $json.target_beneficiaries || '',
      ownership_model: normalizedOwnership,
      productive_uses: $json.productive_uses || [],
      estimated_cost_usd: Number($json.estimated_cost_usd),
      existing_funding: $json.existing_funding || '',
      project_stage: $json.project_stage || 'concept',
      community_engagement: $json.community_engagement || '',
      additional_context: $json.additional_context || '',
      debt_preference: $json.debt_preference || 'grant_preferred'
    },
    validation: {
      status: 'valid',
      timestamp: new Date().toISOString()
    }
  }
}];

const intake = $json.project_intake;

// Score M300 alignment
let score = 50; // Base score

// Ownership scoring
const ownershipScores = {
  'community_cooperative': 30,
  'public_utility': 25,
  'public_community_hybrid': 28,
  'private_with_benefit_sharing': 10,
  'private_ipp': 0
};
score += ownershipScores[intake.ownership_model] || 0;

// Productive use bonus
if (intake.productive_uses && intake.productive_uses.length > 0) {
  score += 10;
}

// Debt preference bonus
if (intake.debt_preference === 'grant_only') {
  score += 10;
}

// Cap at 100
score = Math.min(score, 100);

// Determine debt sensitivity tier
let debtTier = 'tier_1';
if (intake.ownership_model === 'private_ipp') {
  debtTier = 'tier_3';
} else if (intake.ownership_model === 'private_with_benefit_sharing') {
  debtTier = 'tier_2';
}

// Generate grant-suitable elements
const grantSuitable = [];
if (intake.ownership_model === 'community_cooperative') {
  grantSuitable.push('Community cooperative ownership eliminates profit extraction');
}
if (intake.ownership_model.includes('public')) {
  grantSuitable.push('Public ownership keeps infrastructure in government hands');
}
if (intake.productive_uses && intake.productive_uses.length > 0) {
  grantSuitable.push(`Productive use component: ${intake.productive_uses.join(', ')}`);
}
grantSuitable.push('Last-mile rural electrification focus');
if (intake.debt_preference === 'grant_only') {
  grantSuitable.push('Explicit grant-only preference aligns with M300 recommendations');
}

// Generate debt risks
const debtRisks = [];
if (intake.ownership_model === 'private_ipp') {
  debtRisks.push('Private IPP model may require sovereign guarantees');
  debtRisks.push('Profit extraction creates capital flight risk');
} else if (intake.ownership_model.includes('community') || intake.ownership_model.includes('public')) {
  debtRisks.push('None identified under current structure');
}

// Generate private capital risks
const privateRisks = [];
if (intake.ownership_model !== 'private_ipp') {
  privateRisks.push('If private developer introduced later, ensure community retains asset ownership');
  privateRisks.push('Avoid performance guarantees that create contingent government liabilities');
}

// Generate alignment narrative
const alignmentLevel = score >= 70 ? 'strong' : (score >= 50 ? 'moderate' : 'weak');
const narrative = `This ${intake.technology_type.replace(/_/g, ' ')} project in ${intake.country} demonstrates ${alignmentLevel} alignment with M300 debt-sensitivity principles (score: ${score}/100). The ${intake.ownership_model.replace(/_/g, ' ')} ownership model ${score >= 70 ? 'supports grant eligibility by ensuring revenues remain local and no sovereign debt is created' : 'may face challenges with grant funders who prefer community/public ownership'}. ${intake.productive_uses.length > 0 ? 'The productive use component strengthens the business case for grant investment.' : ''}`;

return [{
  json: {
    project_intake: intake,
    policy_interpretation: {
      project_name: intake.project_name,
      m300_alignment_score: score,
      alignment_narrative: narrative,
      ownership_classification: intake.ownership_model,
      grant_suitable_elements: grantSuitable,
      debt_exposure_risks: debtRisks,
      private_capital_risks: privateRisks,
      community_ownership_justification: `The ${intake.ownership_model.replace(/_/g, ' ')} structure keeps revenues within ${intake.country}, builds local capacity, and prevents capital flight that occurs when external investors extract profits.`,
      assumptions_list: [
        'Project entity is legally registered',
        'Land/site tenure is secured',
        'Community engagement is documented',
        'Demand assessment confirms viability'
      ],
      recommended_framing: `Position as ${intake.ownership_model === 'community_cooperative' ? 'community-led' : 'locally-owned'} energy access project that advances M300 electrification goals without adding to ${intake.country}'s debt burden.`,
      debt_sensitivity_tier: debtTier
    }
  }
}];

const intake = $json.project_intake;
const interpretation = $json.policy_interpretation;

// Embedded grants database (subset)
const grants = [
  {
    id: 'geapp_minigrid',
    funder_name: 'Global Energy Alliance for People and Planet (GEAPP)',
    instrument_type: 'grant',
    priority_countries: ['Nigeria', 'Kenya', 'Ethiopia', 'DRC', 'India', 'Indonesia'],
    regions: ['Sub-Saharan Africa', 'South Asia', 'Southeast Asia'],
    thematic_focus: ['mini_grids', 'productive_use', 'distributed_renewables'],
    min_usd: 150000,
    max_usd: 500000,
    debt_tier: 'tier_1',
    community_support: true
  },
  {
    id: 'amsf_rbf',
    funder_name: 'Africa Mini-Grid Support Facility (AMSF)',
    instrument_type: 'results_based_grant',
    priority_countries: [],
    regions: ['West Africa', 'East Africa', 'Southern Africa'],
    thematic_focus: ['mini_grids'],
    min_usd: 100000,
    max_usd: 1000000,
    debt_tier: 'tier_2',
    community_support: true
  },
  {
    id: 'gcf_sap',
    funder_name: 'Green Climate Fund - Simplified Approval Process',
    instrument_type: 'grant',
    priority_countries: [],
    regions: ['Africa', 'Asia', 'Latin America', 'Pacific'],
    thematic_focus: ['climate_mitigation', 'climate_adaptation', 'renewable_energy'],
    min_usd: 250000,
    max_usd: 10000000,
    debt_tier: 'tier_1',
    community_support: true
  },
  {
    id: 'gavi_cceop',
    funder_name: 'Gavi Cold Chain Equipment Optimization Platform (CCEOP)',
    instrument_type: 'grant',
    priority_countries: ['Nigeria', 'DRC', 'Ethiopia', 'Pakistan', 'India'],
    regions: ['Gavi-eligible countries'],
    thematic_focus: ['vaccine_cold_chain', 'health_facility_electrification'],
    min_usd: 50000,
    max_usd: 5000000,
    debt_tier: 'tier_1',
    community_support: true
  },
  {
    id: 'usadf',
    funder_name: 'US African Development Foundation',
    instrument_type: 'grant',
    priority_countries: [],
    regions: ['Sub-Saharan Africa'],
    thematic_focus: ['community_enterprise', 'productive_use', 'energy_access'],
    min_usd: 50000,
    max_usd: 250000,
    debt_tier: 'tier_1',
    community_support: true
  },
  {
    id: 'power_africa_health',
    funder_name: 'Power Africa Health Electrification Initiative',
    instrument_type: 'grant',
    priority_countries: ['Nigeria', 'Kenya', 'Tanzania', 'Uganda', 'Ethiopia'],
    regions: ['Sub-Saharan Africa'],
    thematic_focus: ['health_facility_electrification'],
    min_usd: 100000,
    max_usd: 2000000,
    debt_tier: 'tier_1',
    community_support: true
  }
];

// Scoring function
function scoreGrant(grant, intake) {
  let geoScore = 0, thematicScore = 0, sizeScore = 0, ownershipScore = 0, eligScore = 70;
  let redFlags = [];

  // Geography (25%)
  if (grant.priority_countries.map(c => c.toLowerCase()).includes(intake.country.toLowerCase())) {
    geoScore = 100;
  } else if (grant.regions.some(r => r.toLowerCase().includes('africa'))) {
    geoScore = 60;
  }

  // Thematic (30%)
  const techLower = intake.technology_type.toLowerCase();
  if (grant.thematic_focus.some(t => techLower.includes(t.replace('_', '')) || t.includes(techLower.split('_')[0]))) {
    thematicScore = 100;
  } else if (grant.thematic_focus.includes('energy_access') || grant.thematic_focus.includes('renewable_energy')) {
    thematicScore = 60;
  } else {
    thematicScore = 30;
  }

  // Health-specific matching
  if (techLower.includes('health') || (intake.productive_uses && intake.productive_uses.some(u => u.includes('cold_chain') || u.includes('medical')))) {
    if (grant.thematic_focus.includes('health_facility_electrification') || grant.thematic_focus.includes('vaccine_cold_chain')) {
      thematicScore = 100;
    }
  }

  // Size (15%)
  if (intake.estimated_cost_usd >= grant.min_usd && intake.estimated_cost_usd <= grant.max_usd) {
    sizeScore = 100;
  } else if (intake.estimated_cost_usd >= grant.min_usd * 0.5 && intake.estimated_cost_usd <= grant.max_usd * 1.5) {
    sizeScore = 60;
  } else {
    sizeScore = 30;
    redFlags.push('Project cost outside typical funder range');
  }

  // Ownership (20%)
  if (intake.ownership_model === 'community_cooperative' && grant.community_support) {
    ownershipScore = 100;
  } else if (intake.ownership_model.includes('public') || intake.ownership_model.includes('community')) {
    ownershipScore = 80;
  } else {
    ownershipScore = 40;
  }

  // Debt preference check
  if (intake.debt_preference === 'grant_only' && grant.instrument_type !== 'grant' && grant.instrument_type !== 'results_based_grant') {
    redFlags.push('Instrument type may not align with grant-only preference');
  }

  // RBF bridge financing flag
  if (grant.instrument_type === 'results_based_grant') {
    redFlags.push('Results-based payment requires bridge financing for construction');
  }

  // Calculate weighted score
  const baseScore = (geoScore * 0.25) + (thematicScore * 0.30) + (sizeScore * 0.15) + (ownershipScore * 0.20) + (eligScore * 0.10);

  // Apply red flag penalty
  const penalty = Math.min(redFlags.length * 0.05, 0.20);
  const finalScore = Math.round(baseScore * (1 - penalty));

  return { score: finalScore, redFlags };
}

// Score and rank all grants
const scored = grants.map(grant => {
  const { score, redFlags } = scoreGrant(grant, intake);

  const rationale = [];
  if (grant.priority_countries.map(c => c.toLowerCase()).includes(intake.country.toLowerCase())) {
    rationale.push(`${intake.country} is priority country`);
  } else {
    rationale.push(`${intake.country} within regional scope`);
  }
  rationale.push(`Technology: ${intake.technology_type.replace(/_/g, ' ')}`);
  rationale.push(`Cost $${intake.estimated_cost_usd.toLocaleString()} ${intake.estimated_cost_usd >= grant.min_usd && intake.estimated_cost_usd <= grant.max_usd ? 'within' : 'near'} typical range`);
  if (grant.community_support) {
    rationale.push('Supports community ownership models');
  }

  const nextActions = [
    `Review ${grant.funder_name} eligibility requirements`,
    'Prepare project documentation package',
    'Complete demand assessment',
    'Develop financial projections'
  ];

  return {
    funder_id: grant.id,
    funder_name: grant.funder_name,
    instrument_type: grant.instrument_type,
    fit_score: score,
    debt_sensitivity_tier: grant.debt_tier,
    fit_rationale: rationale,
    red_flags: redFlags,
    next_actions: nextActions
  };
});

// Sort by score descending, take top 5
const matches = scored
  .filter(m => m.fit_score >= 30)
  .sort((a, b) => b.fit_score - a.fit_score)
  .slice(0, 5);

// Identify excluded funders
const excluded = scored
  .filter(m => m.fit_score < 30)
  .map(m => ({ funder_name: m.funder_name, exclusion_reason: 'Fit score below threshold' }));

// Generate funding strategy
const topMatch = matches[0];
const strategy = matches.length > 0 
  ? `Lead with ${topMatch.funder_name} application (${topMatch.fit_score}/100 fit score, ${topMatch.instrument_type}). ${matches.length > 1 ? `Consider ${matches[1].funder_name} as secondary option.` : ''} ${intake.debt_preference === 'grant_only' ? 'Prioritize grant instruments to maintain debt-free status.' : ''}`
  : 'No strong matches found. Consider adjusting project parameters or ownership model.';

return [{
  json: {
    project_intake: intake,
    policy_interpretation: interpretation,
    grant_match: {
      project_name: intake.project_name,
      matches: matches,
      excluded_funders: excluded,
      overall_funding_strategy: strategy
    }
  }
}];

const intake = $json.project_intake;
const interpretation = $json.policy_interpretation;
const grantMatch = $json.grant_match;

const targetFunder = grantMatch.matches.length > 0 ? grantMatch.matches[0].funder_name : 'General';

// Generate proposal outline
const proposalOutline = {
  problem_statement: `Approximately [X] people in ${intake.location_description || intake.country} lack access to reliable electricity. ${intake.technology_type.includes('health') ? 'Health facilities operate without reliable power, affecting service delivery and vaccine storage.' : 'This energy poverty constrains economic development and quality of life.'} ${intake.productive_uses.length > 0 ? `Without electricity, productive activities like ${intake.productive_uses.join(', ')} cannot operate at full potential.` : ''}`,

  theory_of_change: `IF ${intake.project_name} is implemented with ${intake.ownership_model.replace(/_/g, ' ')} ownership, THEN ${intake.target_beneficiaries || 'target beneficiaries'} will gain electricity access${intake.productive_uses.length > 0 ? ` AND ${intake.productive_uses.join(', ')} activities will be enabled` : ''}, LEADING TO improved livelihoods, economic opportunities, and demonstrated model for ${intake.ownership_model.includes('community') ? 'community-owned' : 'locally-owned'} electrification in ${intake.country}.`,

  community_ownership_governance: `The project will be owned under a ${intake.ownership_model.replace(/_/g, ' ')} structure. ${intake.ownership_model === 'community_cooperative' ? 'Governance includes: (1) General Assembly of all members meeting quarterly, (2) Elected Management Committee with term limits and gender representation, (3) Trained local operators, (4) Transparent tariff-setting with community input, (5) Revenue allocation policy with maintenance reserves.' : 'Governance arrangements will ensure local participation and accountability.'} ${interpretation.community_ownership_justification}`,

  technical_approach: `${intake.capacity_kw ? intake.capacity_kw + 'kW' : 'Appropriately sized'} ${intake.technology_type.replace(/_/g, ' ')} system serving ${intake.target_beneficiaries || 'target beneficiaries'}. ${intake.capacity_kw ? 'System designed for reliability with battery storage, smart metering, and local maintainability.' : 'Technical specifications to be finalized based on detailed assessment.'} ${intake.productive_uses.length > 0 ? `Productive use loads (${intake.productive_uses.join(', ')}) integrated into system design.` : ''}`,

  affordability_tariff_principles: intake.technology_type.includes('health') || intake.ownership_model.includes('public') 
    ? 'N/A - Public infrastructure funded by grant. Operational costs covered by government recurrent budget.'
    : 'Tariff structure designed around community ability-to-pay: (1) Lifeline rate for basic consumption, (2) Standard rate for higher usage, (3) Productive use rate for daytime loads. Cross-subsidy from productive use supports household affordability. Pre-paid metering for payment discipline. Tariff review every 2 years with community consultation.',

  implementation_plan: 'Phased implementation:\n- Month 1-2: Detailed design, procurement specifications, community mobilization\n- Month 3-4: Procurement, site preparation\n- Month 5-6: Equipment installation and commissioning\n- Month 7-8: Connections, training, handover to local operations\n- Month 9-12: Performance monitoring, optimization, documentation',

  mel_framework: 'Output indicators: Connections completed, capacity installed, system uptime\nOutcome indicators: Beneficiary satisfaction, energy expenditure changes, income changes, productive use activity levels\nData collection: Smart meter analytics, quarterly beneficiary surveys, annual audit\nLearning: Quarterly review meetings, annual case study, knowledge sharing with sector',

  risk_register: `Technical: Equipment failure - mitigated by quality procurement, warranties, service agreements, spare parts\nFinancial: ${intake.technology_type.includes('health') ? 'Budget constraints - mitigated by Ministry commitment to recurrent costs' : 'Payment delays - mitigated by pre-paid metering, community ownership incentives'}\nGovernance: Capacity gaps - mitigated by training, external oversight, term limits\nExternal: Policy changes - mitigated by community ownership providing resilience\n\nDEBT SENSITIVITY: ${interpretation.debt_exposure_risks.join('. ')} This project ${interpretation.debt_sensitivity_tier === 'tier_1' ? 'creates no debt obligations and requires no sovereign guarantees' : 'has debt implications that should be carefully managed'}.`
};

// Generate readiness checklist
const readinessChecklist = [
  { item: 'Legal entity registration', status: 'unknown', notes: 'Verify registration certificate is current and valid', priority: 'critical' },
  { item: 'Land/site documentation', status: 'unknown', notes: 'Obtain lease, allocation letter, or community land agreement', priority: 'critical' },
  { item: 'Community/stakeholder endorsement', status: 'unknown', notes: 'Document formal support from community and relevant authorities', priority: 'critical' },
  { item: 'Demand assessment completed', status: 'not_ready', notes: 'Conduct household/beneficiary survey using funder template if available', priority: 'critical' },
  { item: 'Technical feasibility/design', status: 'not_ready', notes: 'Commission preliminary design from qualified engineer', priority: 'important' },
  { item: 'Detailed budget with quotes', status: 'not_ready', notes: 'Obtain equipment quotes from 2-3 suppliers, develop cost breakdown', priority: 'important' },
  { item: 'Financial projections', status: 'not_ready', notes: 'Develop 5-year model showing revenue, costs, sustainability', priority: 'important' },
  { item: 'Community/co-financing contribution', status: 'unknown', notes: `Document ${intake.existing_funding || 'any committed contributions'} with evidence`, priority: 'important' },
  { item: 'Implementation timeline', status: 'ready', notes: 'Outlined in proposal', priority: 'nice_to_have' },
  { item: 'M&E framework', status: 'ready', notes: 'Outlined in proposal', priority: 'nice_to_have' }
];

// Add health-specific items if relevant
if (intake.technology_type.includes('health') || intake.productive_uses.some(u => u.includes('cold_chain') || u.includes('medical'))) {
  readinessChecklist.splice(3, 0, 
    { item: 'Ministry of Health endorsement', status: 'unknown', notes: 'Obtain formal letter from relevant health authority', priority: 'critical' },
    { item: 'Facility inventory/assessment', status: 'not_ready', notes: 'Complete technical assessment of target facilities', priority: 'critical' }
  );
}

// Generate missing info questionnaire
const missingInfo = [
  `What is the exact location (GPS coordinates) of the project site(s)?`,
  `What is the registration number/date of the ${intake.ownership_model.replace(/_/g, ' ')} entity?`,
  `What is the current energy situation of target beneficiaries? (grid access, diesel, kerosene expenditure)`,
  `What community/co-financing contribution is committed? (amount, cash vs. in-kind, evidence)`,
  `Has any technical feasibility study or assessment been conducted?`,
  `What is the governance structure of the implementing entity? (committee composition, decision-making)`,
  `What permits or approvals are required? (which authorities, current status)`,
  `Who is the primary contact person and their role?`
];

// Add context-specific questions
if (intake.productive_uses.length > 0) {
  missingInfo.push(`What is the current status of productive use anchor(s)? (${intake.productive_uses.join(', ')} - existing or to be developed?)`);
}
if (intake.ownership_model === 'community_cooperative') {
  missingInfo.push('How many registered members does the cooperative have?');
  missingInfo.push('What is the cooperative\'s track record? (years active, previous projects)');
}

return [{
  json: {
    project_intake: intake,
    policy_interpretation: interpretation,
    grant_match: grantMatch,
    proposal_coach: {
      project_name: intake.project_name,
      target_funder: targetFunder,
      proposal_outline: proposalOutline,
      readiness_checklist: readinessChecklist,
      missing_info_questionnaire: missingInfo
    }
  }
}];
